///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_DigitalChangePage
 * @description Digital Change Page 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_DigitalChangePage = async function () {
    const sbmOptions = {
        id: "tx_fn_DigitalChangePage",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_DigitalChangePageReq",
        target: "dlt_audtOpinTp=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_SearchReq",
        target: "dlt_audtOpinTp=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name digitalChangePage
 * @description digital Change Page 처리
 * @param {*} tab tab
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.digitalChangePage = async function (tab) {
    scwin.form = (document.digitalListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_DigitalChangePageReq').get('lastSaveStatCd'));
    if (tab === 1) {
        $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewIsuTab');
    } else {
        if (tab === 2) {
            return;
        } else {
            if (tab === 3) {
                $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewSrtyLpTab');
            } else {
                $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewAttachFileTab');
            }
        }
    }
    scwin.form.action = 'DigitalList.do';
    await scwin.tx_fn_DigitalChangePage();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = "DigitalList.do";
    $c.util.getComponent('dma_DigitalChangePageReq').set('listBzTpCd', "");
    $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
};

